    def add_rat(self, rat_technology, plan_scf_file, rat_scf_file, output_scf, timeout=60, band=None, merge_bts=None):
        """Add RAT technology into given SCF file

        :param string rat_technology: Name of RAT being added. ["GSM"|"WCDMA"|"LTE"|"NR"]. Can also be passed as a list,
        ie: ["GSM", "WCDMA", "LTE", "NR"]
        :param string plan_scf_file: SCF file path with plan configuration.
        :param string rat_scf_file: SCF file path with RAT specific configuration.
        :param string output_scf: Output SCF file path
        :param boolean merge_bts: (optional) Merge BTS.
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param string band: (optional) Support multiple bands, separated by comma, i.e.: "1,2"

        :return dict: dict with list of skipped objects.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-addRat.html
        """

        parameters = {"ratTechnology": rat_technology, "band": band}

        if merge_bts is not None:
            parameters["mergeBTS"] = to_boolean(merge_bts)

        skipped_objects = self._api_client.execute_offline_procedure("addRat", parameters, timeout,
                                                                     plan_scf_file=plan_scf_file,
                                                                     rat_scf_file=rat_scf_file,
                                                                     output_file_name=output_scf)

        return skipped_objects

    def send_snapshot_configuration(self, destination, max_trigger_number, upload_delay_6450, destination_6450,  # noqa: C901
                                    activate_default_triggers,
                                    lss_ipaddress=None, lss_port_number=None, lss_directory=None, fault_number=None,
                                    trigger_type=None, timeout=60, coverage_level=None, filter_keywords=None):
        """
        *** DEPRECATED ***
        *** Use configure_snapshot instead ***
        Send snapshot configuration.

        :param string destination: Diagnostic snapshot destination. One of ["netact"|"lss"|"externalHTTPSServer"].
        :param int max_trigger_number: Maximum number of snapshots by fault triggers per day. [1, 200].
        :param int upload_delay_6450: Snapshot upload delay for fault 6450 [0, 24].
        :param string destination_6450: Snapshot upload destination for fault 6450 One of ["netact"|"lss"|"disabled"].
        :param bool activate_default_triggers: Activate default fault snapshot triggers.
        :param string lss_ipaddress: Optional, LSS ip address.
        :param int lss_port_number: Optional, LSS port number [1, 65535]
        :param string lss_directory: Optional, LSS directory.
        :param int fault_number: Optional, snapshot trigger fault number [0, 99999]
        :param string trigger_type: Optional, snapshot trigger type for fault,
         one of ["onFaultDetection"|"onAlarmSend"|"onFaultCancellation"].
        :param list coverage_level: Optional, available values:
         ['Full', 'Minor', 'Healthcheck', 'FullWithoutRFLogs', 'MinorWithoutRFLogs', 'SystemModuleHealthcheck', 'L1Files']
        :param string filter_keywords: Optional, keywords used to filtering.
        :param int timeout: Time in seconds to wait for positive procedure result.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-sendSnapshotConfiguration.html
        """
        logging.warning('[DEPRECATION WARNING] This keyword is deprecated.'
                        ' Use configure_snapshot instead')
        if destination not in ["netact", "lss", "externalHTTPSServer"]:
            raise_value_error(param="destination",
                              value=str(destination),
                              subpage="tutorial-sendSnapshotConfiguration.html")

        if destination_6450 not in ["netact", "lss", "disabled"]:
            raise_value_error(param="destination_6450",
                              value=str(destination_6450),
                              subpage="tutorial-sendSnapshotConfiguration.html")

        if trigger_type:
            if trigger_type not in ["onFaultDetection", "onAlarmSend", "onFaultCancellation"]:
                raise_value_error(param="trigger_type",
                                  value=str(trigger_type),
                                  subpage="tutorial-sendSnapshotConfiguration.html")

        parameters = {"diagSnapDestination": destination,
                      "maxNumSnapByFaultTrigPerDay": max_trigger_number,
                      "snapshotUploadDelayForFault6450": upload_delay_6450,
                      "snapshotUploadDestinationForFault6450": destination_6450,
                      "actDefaultFaultSnapTriggers": activate_default_triggers}

        if lss_ipaddress or lss_port_number or lss_directory:
            lss_config = {"lssIPaddress": lss_ipaddress,
                          "lssPortNo": lss_port_number,
                          "directory": lss_directory}
            lss_config = {key: value for key, value in lss_config.items() if value is not None}
            parameters["lssConfig"] = lss_config

        if fault_number or trigger_type or coverage_level or filter_keywords:
            fault_snapshot_triggers = {"faultNumber": fault_number,
                                       "triggerType": trigger_type,
                                       "snapshotCoverageLevel": coverage_level,
                                       "snapshotFilterKeywords": filter_keywords}
            fault_snapshot_triggers = {key: value for key, value in fault_snapshot_triggers.items() if
                                       value is not None}
            parameters["faultSnapshotTriggers"] = fault_snapshot_triggers

        return self._api_client.execute_procedure("sendSnapshotConfiguration", parameters, timeout)

    def snapshot_cancel(self, timeout=360, reason=None):
        """
        Snapshot cancel

        :param int timeout: Timeout for the operation.
        :param string reason: Optional. e.g enter "PowerReset" to cancel the remote snapshot triggered by power reset.
        :raises AdminApiProcedureFailureException: If response status equals 'failed' it returns that exception.
        :return str: Status of the operation.
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-snapshotCancel.html
        """
        parameters = {}
        if reason:
            parameters["reason"] = reason

        return self._api_client.execute_procedure("snapshotCancel", parameters, timeout)

    def configure_uplane_l1_iq_data(self, capture_on_event, dl_nr_subcell_list=None, ul_nr_subcell_list=None,   # noqa: C901
                                    dl_lte_subcell_list=None, ul_lte_subcell_list=None,
                                    capture_on_event_bb_ru=None, capture_ru_list=None, buffer_cycle=None,
                                    capture_frame_offset=None, timeout=120, detailed_output=False, **kwargs):

        """
        .. note::
            SUPPORTS CUSTOMER API ONLY

        Configure UPlaneL1IQData

        :param bool capture_on_event: True or False
        :param list dl_nr_subcell_list: optional, but one of dlNrSubcellList|ulNrSubcellList|
                                         dlLteCellList|ulLteCellList must be configured, maxItems is 4,
                                         not applicable when "captureOnEventFromBBUAndRU" is true.
        :param list ul_nr_subcell_list: optional, but one of dlNrSubcellList|ulNrSubcellList|
                                         dlLteCellList|ulLteCellList must be configured, maxItems is 4.
        :param list dl_lte_subcell_list: optional, but one of dlNrSubcellList|ulNrSubcellList|
                                          dlLteCellList|ulLteCellList must be configured,maxItems is 4,
                                          not applicable when "captureOnEventFromBBUAndRU" is true
        :param list ul_lte_subcell_list: optional, but one of dlNrSubcellList|ulNrSubcellList|
                                          dlLteCellList|ulLteCellList must be configured,maxItems is 4,
                                          not applicable when "captureOnEventFromBBUAndRU" is true
        :param bool capture_on_event_bb_ru: True or False (optional, default false, can be set to true only when
                                                            captureOnEvent is true)
        :param list capture_ru_list: (optional, only applicable when "captureOnEventFromBBUAndRU" is true,
         if configured minItem is 1, all radios got from getUPlaneL1IQCaptureRMODAndAntennaList should be configured)
        :param string buffer_cycle: optional: "2frames"/"4frames"/"8frames"/"16frames"/"32frames"/"64frames"/"128frames"/
         "256frames"/"512frames"/"1024frames", only applicable when "captureOnEventFromBBUAndRU" is true, default "1024frames"
        :param int capture_frame_offset: optional, [<0-(bufferCycle(1024 by default)-1)>],
         only applicable when "captureOnEventFromBBUAndRU" is true, default 0
        :param int timeout: (optional) Timeout for the operation, defaults to 120
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises DataNotAvailable: If Configure UPlaneL1IQData status has not been provided by M-Plane.
        :raises KeyError: If none of dlNrSubcellList|ulNrSubcellList|dlLteCellList|ulLteCellList is provided
        :raises ValueError: If none of dlNrSubcellList|ulNrSubcellList|dlLteCellList|ulLteCellList is list object
        :return: str: status of the operation or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-configureUPlaneL1IQData.html
        """

        params = [dl_nr_subcell_list, ul_nr_subcell_list, dl_lte_subcell_list, ul_lte_subcell_list]

        if not any(params):
            msg = "One of dl_nr_subcell_list | ul_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list " \
                  "must be configured"
            raise KeyError(msg)

        params = [item for item in params if isinstance(item, list)]
        if not params:
            msg = "Params dl_nr_subcell_list | ul_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list must be " \
                  "passed as lists"
            raise ValueError(msg)

        if capture_on_event_bb_ru:
            temp_params = [item for item in params if isinstance(item, list)]
            try:
                temp_params.remove(ul_nr_subcell_list)
                if any(temp_params):
                    msg = "l_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list are not applicable when " \
                          "capture_on_event_bb_ru is set"
                    raise KeyError(msg)
            except ValueError:
                pass

            if not isinstance(capture_ru_list, list):
                msg = "Param capture_ru_list must be passed as a list"
                raise ValueError(msg)

        parameters = {"dlNrSubcellList": dl_nr_subcell_list,
                      "ulNrSubcellList": ul_nr_subcell_list,
                      "dlLteCellList": dl_lte_subcell_list,
                      "ulLteCellList": ul_lte_subcell_list,
                      "captureOnEvent": capture_on_event,
                      "captureOnEventFromBBUAndRU": capture_on_event_bb_ru,
                      "captureRUList": capture_ru_list,
                      "bufferCycle": buffer_cycle,
                      "captureFrameOffset": capture_frame_offset}

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure(name="configureUPlaneL1IQData",
                                                               parameters=parameters,
                                                               timeout=timeout,
                                                               )
        if response is None:
            raise DataNotAvailable("Configure UPlaneL1IQData status has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_configuration(self, remove_operator_certificates=False, remove_user_account_credentials=False,
                            timeout=500, detailed_output=False, reset_type=None, **kwargs):
        """
        Reset configuration.

        :param boolean remove_operator_certificates: Remove operator certificates
        :param boolean remove_user_account_credentials: Remove user account credentials
        :param Union[int,str] timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param str reset_type: Type of the performed reset. Added via CNI-70685. One of: ["Configuration"|
        "ConfigurationWithSecurityCredentials"|"ConfigurationWithOperatorCertificates"|
        "ConfigurationWithLocalUserCredentials"|"ConfigurationWithResetOnlyActivePartitionAndRestoreNcf"|
        "ConfigurationWithDiagnosticAndRecoverySw"]. "ConfigurationWithDiagnosticAndRecoverySw" option is only available
        from SBTS23R2 onwards (CB007500).
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict
                     More details (content of requestMessage is returned data):
                     https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-configurationReset.html
        """
        parameters = {"removeOperatorCertificates": remove_operator_certificates,
                      "removeUserAccountCredentials": remove_user_account_credentials}

        if reset_type:
            if reset_type not in ("Configuration", "ConfigurationWithSecurityCredentials", "ConfigurationWithOperatorCertificates",
                                  "ConfigurationWithLocalUserCredentials", "ConfigurationWithResetOnlyActivePartitionAndRestoreNcf",
                                  "ConfigurationWithDiagnosticAndRecoverySw"):
                raise_value_error(param="reset_type",
                                  value=str(reset_type),
                                  subpage="tutorial-configurationReset.html")
            parameters["resetType"] = reset_type

        response = self._api_client.execute_customer_procedure("configurationReset", parameters, timeout)

        if response.get(self._provided_content.request_message) is None:
            raise DataNotAvailable("Configuration reset result has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

