    def _get_unexpected_alarms(self, alarms):
        unexpected_alarms = list(filter(
            lambda a: not any(validator.check(a) for validator in self._allowed_alarm_validators), alarms))
        if unexpected_alarms:
            return unexpected_alarms

    def get_unexpected_historical_alarms(self, load_history=False, timeout=60):
        """
        Get unexpected historical alarms.

        :param boolean load_history: load entire BTS history (may significantly extent time for request)
        :param int timeout: Time to wait for positive procedure result.
        :return list: List of unexpected alarms.

        """
        return self._get_unexpected_alarms(self.get_historic_alarms(load_history=load_history, timeout=timeout))
